  else; write(lbu__) 'SNOWSOIL_MOD%WV                                                                                 ', -1_8; endif
  if (allocated(WI)) then; write(lbu__) 'SNOWSOIL_MOD%WI                                                                                 ', int(storage_size(WI)/8,8)*size(WI,kind=8), WI
  else; write(lbu__) 'SNOWSOIL_MOD%WI                                                                                 ', -1_8; endif
  if (allocated(dens)) then; write(lbu__) 'SNOWSOIL_MOD%dens                                                                               ', int(storage_size(dens)/8,8)*size(dens,kind=8), dens
  else; write(lbu__) 'SNOWSOIL_MOD%dens                                                                               ', -1_8; endif
  if (allocated(dz)) then; write(lbu__) 'SNOWSOIL_MOD%dz                                                                                 ', int(storage_size(dz)/8,8)*size(dz,kind=8), dz
