  if (allocated(cs)) then; write(lbu__) 'SNOWSOIL_MOD%cs                                                                                 ', int(storage_size(cs)/8,8)*size(cs,kind=8), cs
  else; write(lbu__) 'SNOWSOIL_MOD%cs                                                                                 ', -1_8; endif
  write(lbu__) 'SNOWSOIL_MOD%itop                                                                               ', int(storage_size(itop)/8,8)*1_8, itop
END SUBROUTINE DUMP_SNOWSOIL_MOD
SUBROUTINE DUMP_OUT_MOD(lbu__)
